import {TILES} from './engine.mjs';
const COORDS=[[1,1],[1,2],[1,3],[1,4],[1,5],[2,5],[3,5],[4,5],[5,5],[5,4],[5,3],[5,2],[5,1],[4,1],[3,1],[2,1]];
const COLORS={start:'#528060',opportunity:'#328c77',expense:'#c77e63',learn:'#9182b2',market:'#699eae',salary:'#c19a47'};
const PAWNS=['#176f64','#d29b36','#7061a3','#ba654e','#3d83ac','#7c8a3d'];
const NAMES={vi:{start:'Khởi đầu',opportunity:'Cơ hội',expense:'Bất ngờ',learn:'Kiến thức',market:'Thị trường',salary:'Thu nhập'},en:{start:'Start',opportunity:'Opportunity',expense:'Unexpected',learn:'Knowledge',market:'Market',salary:'Income'}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function matchBoard(players,focusSeat,turn,lang='vi'){
 const vi=lang==='vi',focus=players[focusSeat],game=focus?.game||{},month=game.month||0,dice=game.dice;
 return `<div class="board match-board" role="list" aria-label="${vi?'Bàn cờ Money Lab 16 ô':'Money Lab 16-space board'}">${TILES.map((type,i)=>{const occupants=players.map((p,seat)=>({p,seat})).filter(({p})=>p.game?.position===i);return `<div role="listitem" class="tile match-tile ${[0,4,8,12].includes(i)?'corner':''} ${i===game.position?'active':''} ${occupants.some(x=>x.seat===turn)?'turn-space':''}" style="grid-row:${COORDS[i][0]};grid-column:${COORDS[i][1]};--tile-color:${COLORS[type]}" aria-label="${i+1}. ${NAMES[lang][type]}${occupants.length?': '+occupants.map(x=>esc(x.p.name)).join(', '):''}"><span class="tile-num">${String(i+1).padStart(2,'0')}</span><span class="game-art game-art-${type}" aria-hidden="true"></span><span class="tile-label">${NAMES[lang][type]}</span><span class="match-pawns">${occupants.map(({p,seat})=>`<span class="match-pawn ${seat===turn?'is-turn':''} ${seat===focusSeat?'is-you':''}" style="--pawn-color:${PAWNS[seat%6]}" title="${esc(p.name)}" aria-label="${esc(p.name)}${seat===turn?(vi?' · Đang đi':' · Current turn'):''}">${seat+1}</span>`).join('')}</span></div>`;}).join('')}<div class="board-center match-center"><span class="center-kicker">THE FINANCIAL PLAYGROUND</span><img class="board-world" src="./assets/money-town-v1.png" width="360" height="360" alt="" decoding="async"><div class="center-title">MONEY LAB</div><span class="match-center-player">${esc(focus?.name)}</span><span class="match-month">${vi?'THÁNG':'MONTH'} ${String(month).padStart(2,'0')} / 12</span><div class="dice match-dice" aria-label="${vi?'Xúc xắc':'Die'} ${dice||''}">${dice?['','⚀','⚁','⚂','⚃','⚄','⚅'][dice]:'◇'}</div><span class="match-direction">${vi?'Đi quanh bàn cờ theo chiều kim đồng hồ':'Travel clockwise around the board'} ↻</span></div></div><div class="match-legend" aria-label="${vi?'Quân cờ người chơi':'Player tokens'}">${players.map((p,seat)=>`<span class="${seat===turn?'legend-turn':''}"><i style="--pawn-color:${PAWNS[seat%6]}">${seat+1}</i>${esc(p.name)}${seat===turn?`<small>${vi?'Đang đi':'Turn'}</small>`:''}</span>`).join('')}</div>`;
}
